-- WEC-660 step 2 of 3 · Greek→English ingredient glossary, 2026-09-02.
--
-- «Menu Fitpal New» column F has NO English equivalent, so desc_en could not
-- simply be copied. Rather than free-translating 316 sentences (inconsistent,
-- unauditable), the 268 distinct ingredient TERMS were translated once and the
-- English strings are derived by exact-token mapping. 242 needed translating;
-- 26 were already Latin script (Guacamole, Edamame, Ginger, Kale, Ketchup…)
-- and pass through unchanged.
--
-- Exact-token matching only — never substring replacement, which would turn
-- «Κόκκινη πιπεριά» into "Κόκκινη Pepper".
--
-- Kept as a table, not a one-off script: the same mapping is needed for every
-- future catalogue import and for the admin when new ingredients appear.
-- Source of truth mirrored at docs/catalogue-2026-09/ingredient-glossary-el-en.tsv
--
-- Applied to the live project as migration 20260902150005.

create table if not exists ingredient_glossary (
  el text primary key,
  en text not null,
  created_at timestamptz not null default now()
);

comment on table ingredient_glossary is
  'EL→EN ingredient terms used to derive dishes.desc_en from the Greek Υλικά list (WEC-660).';

alter table ingredient_glossary enable row level security;

drop policy if exists ingredient_glossary_public_read on ingredient_glossary;
create policy ingredient_glossary_public_read
  on ingredient_glossary for select using (true);

drop policy if exists ingredient_glossary_admin_all on ingredient_glossary;
create policy ingredient_glossary_admin_all
  on ingredient_glossary for all using (public.is_admin()) with check (public.is_admin());

